  n_corridor: { label: 'Creep down the corridor', skill: 'sneak', mod: 0, noise: 0, failNoise: 2, clues: 0, ok: 'Past the sleeping postmen, not a whisker out of place.', fail: 'A postman wakes up. Postmen and {d} have history.' },
  n_shoulder: { label: 'Shoulder through every door', skill: 'muscle', mod: -1, noise: 2, failNoise: 3, clues: 1, ok: 'Bang, bang, bang. Through to the mail car.', fail: 'The last door is steel. {d}\'s shoulder is not.' },
  n_crowbar: { label: 'Crowbar the mail car', skill: 'muscle', mod: 0, noise: 2, failNoise: 3, clues: 1, ok: 'The doors pop. Mail sacks, as far as the eye can see.', fail: 'The crowbar bends. The door doesn\'t.' },
  n_sniffbags: { label: 'Sniff out the sacks with money in', skill: 'nose', mod: 0, noise: 0, failNoise: 2, clues: 0, ok: 'Fresh fivers smell like nothing else. {d} picks the right sacks.', fail: 'Every sack smells of postcards from the seaside.' },
  n_sorter: { label: 'Pose as a postal sorter and sort it into your bags', skill: 'disguise', mod: 0, noise: 0, failNoise: 2, clues: 0, ok: 'One for the Post Office, three for us. One for the Post Office...', fail: 'The real sorters ask which depot {d} is from.' },
  n_uncouple: { label: 'Uncouple the carriages', skill: 'muscle', mod: 0, noise: 1, failNoise: 2, clues: 0, ok: 'Clunk. The guards\' carriages roll gently away into the night.', fail: 'The coupling is rusted solid.' },
