  n_jumpoff: { label: 'Jump off at the cutting', skill: 'agility', mod: 0, noise: 0, failNoise: 2, clues: 0, ok: 'Sacks out, crew out, roll down the bank. Gone into the fields.', fail: 'The bank is a nettle patch.' },
